import{_ as a,o as t,c as s,a0 as o}from"./chunks/framework.DQOulFGV.js";const u=JSON.parse('{"title":"Back up a Mac to a NAS","description":"Encrypted, scheduled Mac backups to a Synology, QNAP or any other NAS with Keelhaven — as a share mounted in Finder, or over SFTP with an SSH key.","frontmatter":{"title":"Back up a Mac to a NAS","description":"Encrypted, scheduled Mac backups to a Synology, QNAP or any other NAS with Keelhaven — as a share mounted in Finder, or over SFTP with an SSH key."},"headers":[],"relativePath":"guides/nas.md","filePath":"guides/nas.md"}'),n={name:"guides/nas.md"};function i(r,e,h,l,d,c){return t(),s("div",null,[...e[0]||(e[0]=[o(`<h1 id="back-up-a-mac-to-a-nas" tabindex="-1">Back up a Mac to a NAS <a class="header-anchor" href="#back-up-a-mac-to-a-nas" aria-label="Permalink to &quot;Back up a Mac to a NAS&quot;">​</a></h1><p>Keelhaven encrypts the folders you pick on your Mac and stores them on your NAS. Anyone who opens that folder on the NAS sees encrypted data and nothing else.</p><p>There are two ways to reach it. Start with the first unless you already use SSH keys.</p><h2 id="the-simple-way-a-mounted-share" tabindex="-1">The simple way: a mounted share <a class="header-anchor" href="#the-simple-way-a-mounted-share" aria-label="Permalink to &quot;The simple way: a mounted share&quot;">​</a></h2><ol><li>In Finder, choose <strong>Go → Connect to Server…</strong>, enter <code>smb://</code> and your NAS&#39;s name — <code>smb://nas.local</code> — and open the shared folder you want backups in.</li><li>In Keelhaven, click the lighthouse in the menu bar, then <strong>Add Backup Plan…</strong>, and pick your folders.</li><li>On the next step click <strong>Choose…</strong> and select a folder on the share. It is under <strong>Locations</strong> in the sidebar.</li><li>Choose an encryption password and a schedule.</li></ol><p>The share has to be mounted when a backup runs. If it is not, that run fails and Keelhaven tells you. Nothing is lost: the next run picks up everything that changed since the last good one.</p><h2 id="without-mounting-sftp" tabindex="-1">Without mounting: SFTP <a class="header-anchor" href="#without-mounting-sftp" aria-label="Permalink to &quot;Without mounting: SFTP&quot;">​</a></h2><p>Over SFTP, Keelhaven reaches the NAS on its own whenever it is on the network. It signs in with an SSH key and never asks for the NAS password, so key login has to work first.</p><p><strong>1. Check it in Terminal.</strong></p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ssh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> backup@nas.local</span></span></code></pre></div><p>This must sign you in without asking for a password or a passphrase. The first time, it asks whether to trust the NAS — answer yes here, because Keelhaven cannot answer that question for you.</p><p>If it does ask for a password, the NAS does not have your key yet:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ssh-keygen</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -t</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ed25519</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">        # only if you have no key</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ssh-copy-id</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> backup@nas.local</span></span></code></pre></div><p><strong>2. Connect Keelhaven.</strong> On the destination step open <strong>Advanced options</strong> and choose <strong>SFTP / NAS</strong>.</p><table tabindex="0"><thead><tr><th>Field</th><th>What goes in</th></tr></thead><tbody><tr><td>User</td><td>the account on the NAS, such as <code>backup</code></td></tr><tr><td>Host</td><td><code>nas.local</code>, or its IP address</td></tr><tr><td>Port</td><td><code>22</code>, unless you changed it</td></tr><tr><td>Path on server</td><td>the folder for this Mac&#39;s backups, such as <code>/backups/mac</code></td></tr></tbody></table><p>Then the encryption password and the schedule, as above.</p><h3 id="on-a-synology" tabindex="-1">On a Synology <a class="header-anchor" href="#on-a-synology" aria-label="Permalink to &quot;On a Synology&quot;">​</a></h3><ul><li>SFTP is off until you turn it on: <strong>Control Panel → File Services → FTP → Enable SFTP service</strong>.</li><li>Key login needs a home folder to keep the key in: <strong>Control Panel → User &amp; Group → Advanced → Enable user home service</strong>. Synology&#39;s <a href="https://kb.synology.com/en-uk/DSM/tutorial/How_to_log_in_to_DSM_with_key_pairs_as_admin_or_root_permission_via_SSH_on_computers" target="_blank" rel="noreferrer">guide to key pairs</a> covers the rest.</li><li>Over SFTP a Synology usually lists its shared folders at the top level, so the path looks like <code>/backups/mac</code> rather than <code>/volume1/backups/mac</code>. Run <code>sftp backup@nas.local</code>, then <code>ls</code>, to see what yours shows.</li></ul><h2 id="worth-knowing" tabindex="-1">Worth knowing <a class="header-anchor" href="#worth-knowing" aria-label="Permalink to &quot;Worth knowing&quot;">​</a></h2><p><strong>A NAS in the same house is one copy, not two.</strong> It guards against a dead Mac, not against a fire or a burglary. A second plan to <a href="/guides/backblaze-b2">a bucket</a> covers that — <strong>Duplicate Plan…</strong> copies this one to a new destination.</p><p><strong>You can restore without Keelhaven.</strong> The folder holds a standard <a href="https://restic.net" target="_blank" rel="noreferrer">restic</a> repository:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">restic</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -r</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sftp:backup@nas.local:/backups/mac</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> snapshots</span></span></code></pre></div>`,22)])])}const k=a(n,[["render",i]]);export{u as __pageData,k as default};
